        &&& is_page_ptr(self.points_to.ptr(), page_id)
        &&& self.points_to.is_init()
        &&& self.points_to.value().wf_unused(mim_instance)
        &&& self.exposed.provenance() == self.points_to.ptr()@.provenance
    }
